      es: ["Catedral católica.", "Centro de Huambo.", "Restaurada tras la guerra.", "Edificio de piedra blanca."],
      pt: ["Sé Catedral católica.", "Centro do Huambo.", "Restaurada após a guerra.", "Edifício de pedra branca."],
      fr: ["Cathédrale catholique.", "Centre de Huambo.", "Restaurée après la guerre.", "Bâtiment en pierre blanche."],
